#!/usr/bin/env bash
set -Eeuo pipefail

readonly SCRIPT_VERSION="2.65"
readonly ARCHIVE_SHA256="6515cf286bad088d3fed61ca27d131fab9cbb345dee9611f970b7ee267e0db6f"
readonly INSTALL_DIR_NAME="mtproto-panel-v2.65"

for c in base64 tar gzip sha256sum mktemp awk; do
  command -v "$c" >/dev/null 2>&1 || { echo "Required command not found: $c" >&2; exit 1; }
done

if [[ ${EUID:-$(id -u)} -ne 0 && "${1:-}" != "--dry-run" && "${1:-}" != "--diagnostic" && "${1:-}" != "--audit" ]]; then
  echo "Run as root: sudo bash $0" >&2
  exit 1
fi

TMP_DIR="$(mktemp -d /tmp/mtproto-panel-v2.65.XXXXXX)"
cleanup() { rm -rf "$TMP_DIR"; }
trap cleanup EXIT

